def name_operands(region,address,operation):
 if region!='Station' or address not in FUNCTIONS:return operation
 for value,name in ((0x6DA9,'MapPanelState.ItemIndex'),(0x6D75,'MapPanelState.ScreenRequest'),(0x6D7B,'MapPanelState.SectorRequest'),(0x6D90,'MapPanelState.ClipRequest'),
  (0x6304,'MapViewState.Width'),(0xAEB3,'TextWindow.Width'),(0xAEAB,'TextWindow.Height'),(0x99B4,'StationRaster.FillMode')):
  operation=operation.replace('(#'+format(value,'04X')+')','(@'+name+')')
 operation=operation.replace('LD A, #11','LD A, @SystemNameConst.MapPage').replace('LD A, #10','LD A, @StationIrqConst.StationPage')
 operation=operation.replace('CALL NZ, #D0C3','CALL NZ, @Map.SetupMapRasterWindow.Entry').replace('CALL #C000','CALL @Map.DrawMapScene.Entry')
 operation=operation.replace('CALL #C287','CALL @Station.DrawCaptionItem.Entry').replace('CALL #CCD4','CALL @Station.ResetBandMode.Entry')
 operation=operation.replace('LD DE, #0000','LD DE, @MapClipConst.MinCoordinate').replace('SUB #0D','SUB @MapPanelConst.ClipWidthTrim').replace('SUB #0E','SUB @MapPanelConst.ClipHeightTrim')
 return operation
